// src/components/charts/ForecastChart.jsx
import React, { useEffect, useRef } from "react";
import * as d3 from "d3";
import { COLORS } from "../../utils/colors";

export default function ForecastChart({ data, historicalData, title }) {
  const ref = useRef(null);

  useEffect(() => {
    if (!ref.current) return;
    if (!data || data.length === 0) {
      d3.select(ref.current).selectAll("*").remove();
      d3.select(ref.current)
        .append("text")
        .attr("x", "50%")
        .attr("y", "50%")
        .attr("text-anchor", "middle")
        .style("font-family", "Sarabun, sans-serif")
        .style("font-size", "14px")
        .style("fill", COLORS.sub)
        .text("No forecast data available");
      return;
    }

    const margin = { top: 30, right: 30, bottom: 60, left: 60 };
    const width = ref.current.clientWidth || 700;
    const height = 350;
    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    d3.select(ref.current).selectAll("*").remove();

    const svg = d3.select(ref.current)
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    // Prepare data
    const forecastData = data.map(d => ({
      date: new Date(d.Forecast_Date),
      price: d.Forecasted_Price,
      isForecast: true
    }));

    const historicalDataFormatted = (historicalData || []).map(d => ({
      date: new Date(d.Date),
      price: d['Final Price'],
      isForecast: false
    }));

    const allData = [...historicalDataFormatted, ...forecastData];

    if (allData.length === 0) {
      svg.append("text")
        .attr("x", innerWidth / 2)
        .attr("y", innerHeight / 2)
        .attr("text-anchor", "middle")
        .style("font-family", "Sarabun, sans-serif")
        .style("font-size", "14px")
        .style("fill", COLORS.sub)
        .text("No data available");
      return;
    }

    const xDomain = d3.extent(allData, d => d.date);
    const yMin = Math.max(0, d3.min(allData, d => d.price) * 0.85);
    const yMax = d3.max(allData, d => d.price) * 1.15;

    const xScale = d3.scaleTime()
      .domain(xDomain)
      .range([0, innerWidth]);

    const yScale = d3.scaleLinear()
      .domain([yMin, yMax])
      .range([innerHeight, 0]);

    // Grid lines
    svg.append("g")
      .attr("class", "grid")
      .call(d3.axisLeft(yScale)
        .tickSize(-innerWidth)
        .tickFormat("")
      )
      .style("stroke", "#EEF2F7")
      .style("stroke-dasharray", "4,4");

    // Historical line
    if (historicalDataFormatted.length > 0) {
      const lineGen = d3.line()
        .x(d => xScale(d.date))
        .y(d => yScale(d.price))
        .curve(d3.curveMonotoneX);

      svg.append("path")
        .datum(historicalDataFormatted)
        .attr("d", lineGen)
        .attr("fill", "none")
        .attr("stroke", COLORS.accentDeep)
        .attr("stroke-width", 2.5);

      svg.selectAll("circle.historical")
        .data(historicalDataFormatted)
        .enter()
        .append("circle")
        .attr("class", "historical")
        .attr("cx", d => xScale(d.date))
        .attr("cy", d => yScale(d.price))
        .attr("r", 4)
        .attr("fill", COLORS.accentDeep)
        .append("title")
        .text(d => `${d.date.toLocaleDateString()}: ₱${d.price.toFixed(2)}`);
    }

    // Forecast line
    const forecastLine = d3.line()
      .x(d => xScale(d.date))
      .y(d => yScale(d.price))
      .curve(d3.curveMonotoneX);

    svg.append("path")
      .datum(forecastData)
      .attr("d", forecastLine)
      .attr("fill", "none")
      .attr("stroke", COLORS.accent)
      .attr("stroke-width", 3)
      .attr("stroke-dasharray", "6,4");

    // Forecast dots
    svg.selectAll("circle.forecast")
      .data(forecastData)
      .enter()
      .append("circle")
      .attr("class", "forecast")
      .attr("cx", d => xScale(d.date))
      .attr("cy", d => yScale(d.price))
      .attr("r", 5)
      .attr("fill", COLORS.accent)
      .attr("stroke", COLORS.white)
      .attr("stroke-width", 1.5)
      .append("title")
      .text(d => `${d.date.toLocaleDateString()}: ₱${d.price.toFixed(2)} (forecast)`);

    // ===== FIXED AXES SECTION =====
    // Show fewer ticks to prevent crowding
    const totalMonths = allData.length;
    let tickInterval = 2; // Default: show every 2 months
    if (totalMonths > 30) tickInterval = 4;
    else if (totalMonths > 18) tickInterval = 3;

    const xAxis = d3.axisBottom(xScale)
      .ticks(d3.timeMonth.every(tickInterval))
      .tickFormat(d3.timeFormat("%b %Y"));

    const xAxisGroup = svg.append("g")
      .attr("transform", `translate(0,${innerHeight})`)
      .call(xAxis)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "10px")
      .style("color", COLORS.sub);

    // Rotate labels if there are many
    if (allData.length > 15) {
      xAxisGroup.selectAll("text")
        .attr("transform", "rotate(-35)")
        .style("text-anchor", "end")
        .attr("dx", "-0.5em")
        .attr("dy", "0.3em");
    }

    const yAxis = d3.axisLeft(yScale)
      .ticks(6)
      .tickFormat(d => `₱${d.toFixed(0)}`);

    svg.append("g")
      .call(yAxis)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "11px")
      .style("color", COLORS.sub);

    // Legend
    const legend = svg.append("g")
      .attr("transform", `translate(${innerWidth - 180}, -10)`);

    legend.append("line")
      .attr("x1", 0)
      .attr("y1", 0)
      .attr("x2", 25)
      .attr("y2", 0)
      .attr("stroke", COLORS.accentDeep)
      .attr("stroke-width", 2.5);

    legend.append("text")
      .attr("x", 32)
      .attr("y", 4)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "11px")
      .style("fill", COLORS.sub)
      .text("Historical");

    legend.append("line")
      .attr("x1", 110)
      .attr("y1", 0)
      .attr("x2", 135)
      .attr("y2", 0)
      .attr("stroke", COLORS.accent)
      .attr("stroke-width", 3)
      .attr("stroke-dasharray", "6,4");

    legend.append("text")
      .attr("x", 142)
      .attr("y", 4)
      .style("font-family", "Sarabun, sans-serif")
      .style("font-size", "11px")
      .style("fill", COLORS.sub)
      .text("Forecast");

  }, [data, historicalData]);

  return (
    <div 
      ref={ref} 
      style={{ 
        width: "100%", 
        height: 350, 
        background: COLORS.white, 
        borderRadius: 10,
        padding: "10px 0"
      }} 
    />
  );
}
